// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BlockPlacementDef) predicate.BlockPlacementDef {
	return predicate.BlockPlacementDef(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BlockPlacementDef) predicate.BlockPlacementDef {
	return predicate.BlockPlacementDef(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BlockPlacementDef) predicate.BlockPlacementDef {
	return predicate.BlockPlacementDef(sql.NotPredicates(p))
}
